Ltac rgL_tail bd vd Rd Ed SOK n ps pd s4 d4 :=
  stepLD F_7bd90 D_7bd90 bd vd ltac:(addr_norm; rewrite ?Z.add_0_r; exact Rd) ltac:(exact Ed);
