(* [comment removed for export] *)
Lemma rg_H2 : forall regs m (i nfw d4 pdf psrow pdrow : Z),
  (0 <= i < 2 ^ 24)%Z -> (1 <= nfw < 2 ^ 26)%Z -> (0 <= d4 < 2 ^ 26)%Z ->
  getr regs 28 = Z_to_bv 64 nfw -> getr regs 18 = Z_to_bv 64 d4 -> getr regs 10 = Z_to_bv 64 i -> getr regs 20 = Z_to_bv 64 (4 * nfw) ->
  getr regs 29 = Z_to_bv 64 pdf -> getr regs 9 = Z_to_bv 64 psrow -> getr regs 21 = Z_to_bv 64 pdrow ->
  exists regs',
    msteps SEGS (mkst regs (0x7c99c : word) m rom) (mkst regs' (0x7c9b4 : word) m rom)
    /\ getr regs' 7 = Z_to_bv 64 (pdf + 4 * nfw + d4 * i) /\ getr regs' 22 = Z_to_bv 64 psrow /\ getr regs' 23 = Z_to_bv 64 pdrow
    /\ regs_agree (fun r => In r [7; 22; 23]%list) regs regs'.
Proof.
