Lemma rg_Q1 : forall regs m (DX SX k : Z),
  (0 <= DX < 2 ^ 31)%Z -> (0 <= SX < 2 ^ 31)%Z -> (DX mod 32 <> SX mod 32)%Z -> (1 <= k < 32)%Z ->
  getr regs 20 = Z_to_bv 64 (DX mod 32) -> getr regs 30 = Z_to_bv 64 (SX mod 32) -> getr regs 15 = Z_to_bv 64 k ->
  exists regs',
    msteps SEGS (mkst regs (0x7a1dc : word) m rom) (mkst regs' (0x7a234 : word) m rom)
    /\ getr regs' 28 = Z_to_bv 64 (g_hang DX) /\ getr regs' 29 = Z_to_bv 64 (32 - DX mod 32) /\ getr regs' 7 = Z_to_bv 64 32
    /\ getr regs' 31 = Z_to_bv 64 (32 - SX mod 32) /\ getr regs' 15 = Z_to_bv 64 (g_sls DX SX) /\ getr regs' 16 = Z_to_bv 64 (32 - g_sls DX SX)
    /\ getr regs' 8 = Z_to_bv 64 0x1f3a0
    /\ regs_agree (fun r => In r [7; 8; 15; 16; 17; 28; 29; 31]%list) regs regs'.
Proof.
