Lemma rg_Q3 : forall regs m (s DX DW : Z) (mk : word),
  (112 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= DX < 2 ^ 31)%Z -> (1 <= DW)%Z -> (DX mod 32 <> 0)%Z -> (DW < 32 - DX mod 32)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 112)) 8 = true ->
  getr regs 2 = Z_to_bv 64 (s - 112) -> getr regs 6 = Z_to_bv 64 DW -> getr regs 29 = Z_to_bv 64 (32 - DX mod 32) ->
  getr regs 20 = Z_to_bv 64 (DX mod 32) -> getr regs 21 = Z_to_bv 64 11 -> getr regs 18 = mk ->
  exists regs',
    msteps SEGS (mkst regs (0x7a280 : word) m rom)
                (mkst regs' (0x7a5ac : word) (wbytes m (Z_to_bv 64 (s - 112)) (word_to_le_bytes 8 (Z_to_bv 64 1))) rom)
    /\ getr regs' 19 = Z_to_bv 64 1 /\ getr regs' 28 = Z_to_bv 64 0 /\ getr regs' 9 = Z_to_bv 64 0 /\ getr regs' 29 = Z_to_bv 64 0
    /\ getr regs' 5 = Z_to_bv 64 0 /\ getr regs' 26 = Z_to_bv 64 0
    /\ regs_agree (fun r => In r [5; 6; 7; 9; 18; 19; 26; 28; 29]%list) regs regs'.
