(* [comment removed for export] *)
Lemma rg_Q3b : forall regs m (DX : Z),
  (0 <= DX < 2 ^ 31)%Z -> (DX mod 32 = 0)%Z -> getr regs 20 = Z_to_bv 64 (DX mod 32) ->
  exists regs',
    msteps SEGS (mkst regs (0x7a234 : word) m rom) (mkst regs' (0x7a4c8 : word) m rom)
    /\ getr regs' 1 = Z_to_bv 64 0 /\ getr regs' 8 = Z_to_bv 64 0 /\ getr regs' 29 = Z_to_bv 64 0 /\ getr regs' 18 = Z_to_bv 64 0
