(* [comment removed for export] *)
Lemma rg_Q4 : forall (full : bool) regs m (DX SX DW dy sy dwpl swpl datad datas : Z),
  (0 <= DX < 2 ^ 30)%Z -> (0 <= SX < 2 ^ 30)%Z -> (0 <= DW < 2 ^ 30)%Z -> (g_hang DX <= DW)%Z ->
  (if full then 32 <= DW - g_hang DX else DW - g_hang DX < 32)%Z ->
  getr regs 6 = Z_to_bv 64 DW -> getr regs 29 = Z_to_bv 64 (g_hang DX) -> getr regs 28 = Z_to_bv 64 (g_hang DX) -> getr regs 7 = Z_to_bv 64 32 ->
  getr regs 19 = Z_to_bv 64 DX -> getr regs 26 = Z_to_bv 64 SX ->
  getr regs 27 = Z_to_bv 64 dy -> getr regs 23 = Z_to_bv 64 sy -> getr regs 14 = Z_to_bv 64 dwpl -> getr regs 13 = Z_to_bv 64 swpl ->
  getr regs 5 = Z_to_bv 64 datad -> getr regs 22 = Z_to_bv 64 datas ->
  exists regs',
    msteps SEGS (mkst regs (0x7a4c8 : word) m rom) (mkst regs' (0x7a51c : word) m rom)
    /\ getr regs' 31 = Z_to_bv 64 (DW - g_hang DX) /\ getr regs' 30 = Z_to_bv 64 (DX + g_hang DX) /\ getr regs' 26 = Z_to_bv 64 (SX + g_hang DX)
    /\ getr regs' 28 = Z_to_bv 64 ((DW - g_hang DX) / 32)
    /\ (full = true -> getr regs' 29 = Z_to_bv 64 (datad + 4 * (dy * dwpl) + 4 * ((DX + g_hang DX) / 32))
                    /\ getr regs' 9 = Z_to_bv 64 (datas + 4 * (sy * swpl) + 4 * ((SX + g_hang DX) / 32)))
    /\ regs_agree (fun r => In r [7; 9; 26; 28; 29; 30; 31]%list) regs regs'.
Proof.
